export i32 collatz(i32 n) {
  i32 steps = 0;
  while (n != 1) {
    if (n % 2 == 0) { n = n / 2; }
    else { n = n * 3 + 1; }
    steps++;
  }
  return steps;
}

export i32 fib(i32 n) {
  if (n < 2) { return n; }
  i32 a = 0;
  i32 b = 1;
  for (i32 i = 2; i <= n; i++) {
    i32 t = a + b;
    a = b;
    b = t;
  }
  return b;
}

export i32 digitCount(i32 n) {
  if (n < 0) { n = -n; }
  i32 count = 0;
  do {
    count++;
    n = n / 10;
  } while (n > 0);
  return count;
}

export i32 findFirst(i32[] arr, i32 target) {
